using System.Text.Json;
using System.Text.RegularExpressions;

namespace EduTrail.Application.QuestionCatalog
{
    // Replaces {{params.key}} tokens in question.html with values generated by server.py.
    public static class ParamSubstitution
    {
        private static readonly Regex TokenPattern =
            new(@"\{\{params\.(\w+)\}\}", RegexOptions.Compiled);

        public static string Substitute(string html, JsonElement @params)
        {
            return TokenPattern.Replace(html, match =>
            {
                var key = match.Groups[1].Value;
                if (@params.ValueKind == JsonValueKind.Object && @params.TryGetProperty(key, out var val))
                    return val.ValueKind == JsonValueKind.String
                        ? val.GetString()!
                        : val.ToString().Replace("\"", "&quot;");
                return match.Value;
            });
        }
    }
}
